CREATE TABLE tariffs (id BINARY(16) PRIMARY KEY,tenant_id BINARY(16) NOT NULL,code VARCHAR(60) NOT NULL,name VARCHAR(150) NOT NULL,energy_price_per_kwh DECIMAL(10,4) NOT NULL,time_price_per_minute DECIMAL(10,4) NOT NULL,session_fee DECIMAL(10,2) NOT NULL,tax_percent DECIMAL(5,2) NOT NULL,currency VARCHAR(3) NOT NULL,status VARCHAR(20) NOT NULL,valid_from TIMESTAMP(6) NOT NULL,valid_to TIMESTAMP(6),created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,CONSTRAINT uk_tariff_tenant_code UNIQUE(tenant_id,code));
CREATE INDEX idx_tariffs_tenant_status ON tariffs(tenant_id,status);
